{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 도시공원 조례상 경관녹지의 사무관할(서울시 vs 자치구)",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 도시공원 조례 별표 5는 녹지의 사무관할을 서울특별시와 자치구로 구분하며, 경관녹지는 서울특별시 소관 사무를 제외한 완충녹지 및 연결녹지와 함께 자치구가 관할하는 것으로 정하고 있다. 따라서 경관녹지의 사무관할은 원칙적으로 자치구이다.",
          "b_ids": "도시공원:별표5#행3, 도시공원:제32조제1항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "경관녹지 기존시설의 유지관리 소요비용 원칙적 부담 주체",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "서울특별시 도시공원 조례 제32조 제2항은 공원 또는 녹지의 취득·조성 및 기존시설 등에 대한 유지관리 업무의 시행에 따른 소요비용을 제1항의 사무관할 구분에 따라 부담하도록 정하고 있다. 경관녹지는 별표 5에 따라 자치구 사무이므로, 그 기존시설의 유지관리 소요비용은 원칙적으로 자치구가 부담한다.",
          "b_ids": "도시공원:제32조제2항, 도시공원:별표5#행3, 도시공원:제32조제1항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
